INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(9601, '2 Kings 23:2', '2 Kings', 23, 2, '&nbsp;او هغوئ په يو ځائ د مالِک خُدائ کور ته لاړل، چې اِمامان، پېغمبران او باقى نور ټول خلق د واړو نه واخله تر غټو پورې ورسره وُو. د هغوئ ټولو په وړاندې، بادشاه د لوظ هغه ټول کِتاب ولوستلو کوم چې د مالِک خُدائ په کور کښې موندلے شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9602, '2 Kings 23:3', '2 Kings', 23, 3, '&nbsp;هغه د شاهى ستنې سره ودرېدو او د مالِک خُدائ سره يې يو لوظ وکړو چې د هغۀ تابعدارى به کوى او د زړۀ د اخلاصه به د هغۀ ټول قانون او حُکمونه منى او چې د هغه لوظ په مطالبو به عمل کوى، څنګه چې په کِتاب کښې ليکلے شوى دى. او ټولو خلقو دا لوظ ومنلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9603, '2 Kings 23:4', '2 Kings', 23, 4, '&nbsp;بيا يوسياه مشر اِمام خِلقياه له، د هغۀ لاندې اِمامانو او د مالِک خُدائ د کور د ننوتلو د دروازې خادمانو له حُکم ورکړو چې د مالِک خُدائ د کور هغه ټول څيزونه وباسى چې د بعل، د اشيرې بُت او د ستورو په عبادت کښې استعمال شوى وى. بادشاه دا ټول څيزونه د قِدرون د وادۍ په پټو کښې د ښار نه بهر وسوزول او د دې ايرې يې بيت‌ايل ته يوړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9604, '2 Kings 23:5', '2 Kings', 23, 5, '&nbsp;هغۀ بُت پرسته اِمامان لرې کړل چې د يهوداه بادشاهانو مقرر کړى وُو چې کومو د يهوداه په ښارونو کښې په علاقائى عبادتخانو او يروشلم ته نزدې ځايونو کښې قربانۍ پېش کولې، هغه ټول اِمامان يې لرې کړل چا چې بعل، نمر، سپوږمۍ، سيارو او ستورو ته قربانۍ پېش کولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9605, '2 Kings 23:6', '2 Kings', 23, 6, '&nbsp;هغۀ د مالِک خُدائ کور نه د اشيرې بُت نښه لرې کړله، د ښار نه بهر د قِدرون وادۍ ته يې يوړه، وې سوزوله او خاورې يې کړه او د دې ايره يې د عامو خلقو په قبرونو باندې وشيندله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9606, '2 Kings 23:7', '2 Kings', 23, 7, '&nbsp;هغۀ د مالِک خُدائ په کور کښې د اوسېدو هغه کوټې ورانې کړې چې د هغه کور نرانو کنجرانو نيولې وې، چرته چې ښځو د اشيرې بُت دپاره چُوغې جوړولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9607, '2 Kings 23:8', '2 Kings', 23, 8, '&nbsp;د يهوداه په ښارونو کښې چې کوم اِمامان وُو هغه يې يروشلم ته راوستل او په ټول مُلک کښې يې علاقائى عبادتخانه ناپاکه کړه چرته چې هغوئ قربانۍ پېش کړې وې. هغۀ د ښار د حکمران يشوَع د دروازې په خولۀ کښې علاقائى عبادتخانې تباه کړې. دا دروازه ښار ته د ننوتو د دروازې په ګس طرف باندې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9608, '2 Kings 23:9', '2 Kings', 23, 9, '&nbsp;هغه علاقائى اِمامانو ته دا اجازت نۀ وو چې په يروشلم کښې يې د مالِک خُدائ د قربان‌ګاه خِدمت کړے وے، خو چې د هغوئ ملګرو اِمامانو ته کومه پتيره روټۍ مِلاو شوې وه نو هغه يې خوړلے شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9609, '2 Kings 23:10', '2 Kings', 23, 10, '&nbsp;او هغۀ د هنوم په وادۍ کښې د غېرو قومونو د عبادت ځائ توفت هم ناپاک کړو، نو چې هيڅ څوک خپل زوئ يا لور مولک بُت ته د سوزېدونکې نذرانې په توګه نۀ شى قربانى کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9610, '2 Kings 23:11', '2 Kings', 23, 11, '&nbsp;د آسونو هغه مجسمې يې هم لرې کړې چې د يهوداه بادشاه نمر ته وقف کړې وې او چې په دې کښې کومې جنګى ګاډۍ استعمالېدلې هغه يې وسوزولې. (دا د مالِک خُدائ د کور په دربار کښې اېښودے شوې وې، چې د دروازې او د مشر آفسر ناتن مُلک د اوسېدو د کوټې سره نزدې وې.)', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9611, '2 Kings 23:12', '2 Kings', 23, 12, '&nbsp;هغه ټولې قربان‌ګاه چې د يهوداه بادشاهانو د محل په چت باندې د احاز بادشاه د کوټې نه بره جوړې کړې وې نو يوسياه بادشاه هغه راوغورزولې، سره د هغه قربان‌ګاه چې منسى بادشاه د مالِک خُدائ کور په دوو دربارونو کښې اېښې وې، هغۀ قربان‌ګاه ذرې ذرې کړلې او د دې ټُکړې يې د قِدرون په وادۍ کښې واچولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9612, '2 Kings 23:13', '2 Kings', 23, 13, '&nbsp;يوسياه هغه علاقائى عبادتخانې ناپاکې کړې چې سليمان بادشاه د يروشلم نمرخاتۀ طرف ته او د زيتُونو غرۀ جنوبى طرف ته د بې‌کاره بُتانو عبادت دپاره جوړې کړې وې، يعنې د صيدان عستاراتې بُت، د موآب بُت کموس او د عمون بُت مولک.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9613, '2 Kings 23:14', '2 Kings', 23, 14, '&nbsp;يوسياه بادشاه د کاڼو ستنې ټوټې کړې، د اشيرې بُت نښې يې راوغورزولې او چې دا چرته ولاړې وې نو هغه ځائ يې د بنيادمو په هډُوکو باندې پټ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9614, '2 Kings 23:15', '2 Kings', 23, 15, '&nbsp;يوسياه په بيت‌ايل کښې د عبادت هغه ځائ هم راوغورزولو چې د نباط زوئ يربعام بادشاه جوړ کړے وو، چا چې اِسرائيل د ګناه طرف ته بوتلى وُو. يوسياه قربان‌ګاه راوغورزوله، د دې کاڼى يې ټوټې ټوټې او خاورې کړل، هغۀ د اشيرې مجسمه هم وسوزوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9615, '2 Kings 23:16', '2 Kings', 23, 16, '&nbsp;يوسياه مخ واړولو او هلته يې د غرۀ دپاسه څۀ قبرونه وليدل، هډُوکى يې ترې نه رابهر کړل او په قربان‌ګاه باندې يې وسوزول. نو هغه قربان‌ګاه يې ناپاکه کړه، چې د دې هغه پېغمبر ډېر پخوا پېشګوئې کړې وه چې د اختر په وخت کښې يربعام بادشاه د قربان‌ګاه سره ولاړ وو. يوسياه بادشاه وکتل او د هغه پېغمبر قبر يې وليدو چې کوم دا پېشګوئې کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9616, '2 Kings 23:17', '2 Kings', 23, 17, '&nbsp;هغۀ تپوس وکړو، ”دا د چا قبر دے؟“ د بيت‌ايل خلقو ورته ووئيل، ”دا د هغه پېغمبر قبر دے کوم چې د يهوداه نه راغلے وو او د دې پېشګوئې يې کړې وه چې تا د قربان‌ګاه سره وکړل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9617, '2 Kings 23:18', '2 Kings', 23, 18, '&nbsp;يوسياه حُکم وکړو، ”دا هم داسې پرېږدئ، د هغۀ هډُوکى دې څوک نۀ لرې کوى.“ نو د هغۀ هډُوکى يې لرې نۀ کړل او نۀ د هغه پېغمبر هډُوکى لرې کړے شول چې د سامريه نه راغلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9618, '2 Kings 23:19', '2 Kings', 23, 19, '&nbsp;په سامريه کښې يوسياه بادشاه په هر يو ښار کښې علاقائى زيارتونه راوغورزول چې کوم د اِسرائيل بادشاهانو جوړ کړى وُو او د مالِک خُدائ غصه يې راپارولې وه. هغۀ په هغه ټولو قربان‌ګاه باندې هم هغه شان وکړل چې څنګه يې په بيت‌ايل کښې کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9619, '2 Kings 23:20', '2 Kings', 23, 20, '&nbsp;هغۀ د ټولو علاقائى عبادتخانو اِمامان په قربان‌ګاه باندې ووژل چرته چې هغوئ خِدمت کولو او هغۀ په هره قربان‌ګاه باندې د بنيادمو هډُوکى وسوزول او بيا هغه يروشلم ته راواپس شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9620, '2 Kings 23:21', '2 Kings', 23, 21, '&nbsp;نو يوسياه بادشاه خلقو له حُکم ورکړو چې د مالِک خُدائ د هغوئ د خُدائ پاک په درناوى کښې د فسحې اختر وکړئ، لکه څنګه چې د لوظ په کِتاب کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9621, '2 Kings 23:22', '2 Kings', 23, 22, '&nbsp;د قاضيانو د حکومت د وخت نه پس، د دې په شان د فسحې اختر د اِسرائيل يا د يهوداه يو بادشاه هم نۀ وو کړے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9622, '2 Kings 23:23', '2 Kings', 23, 23, '&nbsp;او د يوسياه د بادشاهۍ په اتلسم کال په يروشلم کښې د فسحې اختر وکړے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9623, '2 Kings 23:24', '2 Kings', 23, 24, '&nbsp;په هغه کِتاب کښې د ليکلى شوى قانون عملى کولو دپاره چې خِلقياه اِمام د مالِک خُدائ په کور کښې موندلے وو، يوسياه بادشاه د يروشلم او د نور ټول يهوداه نه ټول جادوګر او قسمت ښودونکى او کورنى ټول بُتان او د غېرو قومونو د عبادت نور ټول حرام څيزونه لرې کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9624, '2 Kings 23:25', '2 Kings', 23, 25, '&nbsp;د هغۀ نه مخکښې هيڅکله هم د هغۀ په شان بادشاه نۀ وو تېر شوے، چا چې د زړۀ د اخلاصه، د ټول عقل او طاقت سره د مالِک خُدائ خِدمت کړے وى او د موسىٰ ټول قانون يې منلے وى، او نۀ وروستو د هغۀ په شان بادشاه پېدا شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9625, '2 Kings 23:26', '2 Kings', 23, 26, '&nbsp;خو منسى بادشاه چې څۀ کړى وُو نو د هغې په وجه د مالِک خُدائ سخته غصه راوچته شوې وه او لا سړه شوې نۀ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9626, '2 Kings 23:27', '2 Kings', 23, 27, '&nbsp;مالِک خُدائ وفرمائيل، ”ما چې د اِسرائيل سره څۀ کړى دى نو هغه به په يهوداه هم وکړم، د يهوداه خلق به زۀ د خپل نظر نه لرې کړم او زۀ به يروشلم رد کړم، کوم ښار او کور چې ما خوښ کړے وو او چې ما فرمائيلى وُو چې هلته به زما عبادت کيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9627, '2 Kings 23:28', '2 Kings', 23, 28, '&nbsp;يوسياه بادشاه چې نور څۀ هم کړى دى هغه د يهوداه د بادشاهانو په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9628, '2 Kings 23:29', '2 Kings', 23, 29, '&nbsp;چې کله يوسياه بادشاه وو، نو د مِصر بادشاه نِکوه فِرعون د فرات سيند له يو لښکر بوتلو چې د اسور بادشاه مدد وکړى. يوسياه بادشاه په مِجدو کښې د مِصرى لښکر سره مخامخ شو او په جنګ کښې ووژلے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9629, '2 Kings 23:30', '2 Kings', 23, 30, '&nbsp;د هغۀ آفسرانو د هغۀ لاش په يوه جنګى ګاډۍ کښې کېښودو او يروشلم ته يې يوړو او هلته په شاهى اديره کښې ښخ کړے شو. د يهوداه خلقو د يوسياه زوئ يهوآخز خوښ کړو او هغه يې بادشاه مقرر کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9630, '2 Kings 23:31', '2 Kings', 23, 31, '&nbsp;يهوآخز د درويشتو کالو وو چې هغه د يهوداه بادشاه شو او هغۀ په يروشلم باندې درې مياشتې حکومت وکړو. د هغۀ مور حموطل وه، چې د لِبناه د ښار د يرمياه لور وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9631, '2 Kings 23:32', '2 Kings', 23, 32, '&nbsp;هغه د خپل پلار نيکۀ په نقش قدم باندې روان وو او هغۀ د مالِک خُدائ خِلاف ګناه وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9632, '2 Kings 23:33', '2 Kings', 23, 33, '&nbsp;د هغۀ بادشاهى په هغه وخت ختمه شوه چې د مِصر بادشاه نِکوه فِرعون د حمات مُلک رِبله ته هغه قېدى بوتلو، نو په يهوداه باندې يې درې زره څلور سوه کلو سپين زر او څلور دېرش کلو سرۀ زر محصُول حواله کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9633, '2 Kings 23:34', '2 Kings', 23, 34, '&nbsp;نِکوه فِرعون د يوسياه زوئ اِلياقيم د يوسياه نه پس د يهوداه بادشاه جوړ کړو او د هغۀ نوم يې يهويقيم ته بدل کړو. نِکوه فِرعون يهوآخز مِصر ته بوتلو او هلته مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9634, '2 Kings 23:35', '2 Kings', 23, 35, '&nbsp;يهويقيم بادشاه د خلقو د دولت په مطابق د هغوئ نه محصُول راغونډولو، چې هغه غوښتونکې پېسې پوره کړى چې د مِصر بادشاه فِرعون له په محصُول کښې ورکولے شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9635, '2 Kings 23:36', '2 Kings', 23, 36, '&nbsp;يهويقيم د پينځويشتو کالو وو چې هغه د يهوداه بادشاه جوړ شو او هغۀ په يروشلم باندې يوولس کاله بادشاهى وکړه. د هغۀ مور زبوده وه چې د روماه ښار د فداياه لور وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9636, '2 Kings 23:37', '2 Kings', 23, 37, '&nbsp;هغه د خپل پلار نيکۀ په نقش قدم باندې روان وو، يهويقيم د مالِک خُدائ خِلاف ګناه وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9637, '2 Kings 24:1', '2 Kings', 24, 1, '&nbsp;کله چې يهويقيم بادشاه وو، نو د بابل بادشاه نبوکدنضر په يهوداه حمله وکړه او درې کاله يې په يهويقيم باندې زور راوړلو چې د هغۀ حکومت ته تسليم شى، بيا يهويقيم بغاوت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9638, '2 Kings 24:2', '2 Kings', 24, 2, '&nbsp;نو مالِک خُدائ د يهويقيم خِلاف د يهوداه د تباه کولو دپاره، د بابل، اسور، موآب او عمون لښکرې ولېږلې، لکه څنګه چې مالِک خُدائ د خپلو خِدمت کوونکو پېغمبرانو په ذريعه فرمائيلى وُو چې هغه به داسې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9639, '2 Kings 24:3', '2 Kings', 24, 3, '&nbsp;د مالِک خُدائ په حُکم باندې داسې ځکه وشول چې د يهوداه خلق د خپل حضور نه لرې کړى، دا د هغه ټولو ګناهونه په وجه چې منسى بادشاه کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9640, '2 Kings 24:4', '2 Kings', 24, 4, '&nbsp;د هغه بې‌ګناه خلقو د وينې په وجه چې هغۀ توئ کړې وه، نو مالِک خُدائ ځکه منسى نۀ شو معاف کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9641, '2 Kings 24:5', '2 Kings', 24, 5, '&nbsp;نور هر څۀ چې يهويقيم کړى دى هغه د يهوداه د بادشاهانو په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9642, '2 Kings 24:6', '2 Kings', 24, 6, '&nbsp;يهويقيم مړ شو او د هغۀ زوئ يهوياکين د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9643, '2 Kings 24:7', '2 Kings', 24, 7, '&nbsp;د مِصر بادشاه او د هغۀ لښکر بيا هيڅکله هم د مِصر نه لا نۀ ړل، ځکه چې اوس د بابل بادشاه د مِصر ټوله علاقه قبضه کړې وه، دا د فرات سيند نه واخله د مِصر شمالى سرحد پورې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9644, '2 Kings 24:8', '2 Kings', 24, 8, '&nbsp;يهوياکين د اتلسو کالو وو چې هغه د يهوداه بادشاه شو او هغۀ په يروشلم باندې درې مياشتې بادشاهى وکړه. د هغۀ مور نحشتا وه چې د يروشلم د الناتن لور وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9645, '2 Kings 24:9', '2 Kings', 24, 9, '&nbsp;يهوياکين د مالِک خُدائ په نظر کښې بد عمل کولو هم هغه شان لکه څنګه عمل چې د هغۀ پلار کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9646, '2 Kings 24:10', '2 Kings', 24, 10, '&nbsp;د هغۀ په دور کښې د بابل فوج د يروشلم خِلاف روان شو چې مشرى يې د نبوکدنضر بادشاه آفسرانو کوله او يروشلم يې محاصره کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9647, '2 Kings 24:11', '2 Kings', 24, 11, '&nbsp;د محاصرې په دوران کښې نبوکدنضر په خپله يروشلم ته راغلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9648, '2 Kings 24:12', '2 Kings', 24, 12, '&nbsp;او يهوياکين بادشاه، سره د خپلې مور، زامنو، آفسرانو او سره د محل د آفسرانو بابليانو ته تسليم شو. د نبوکدنضر د بادشاهۍ په اتم کال هغۀ يهوياکين قېدى کړو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9649, '2 Kings 24:13', '2 Kings', 24, 13, '&nbsp;او د محل او د مالِک خُدائ د کور ټولې خزانې يې بابل ته يوړې. لکه څنګه چې مالِک خُدائ پېشګوئې کړې وه، نبوکدنضر د سرو زرو هغه ټول سامان مات کړو کوم چې سليمان بادشاه د مالِک خُدائ د کور دپاره جوړ کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9650, '2 Kings 24:14', '2 Kings', 24, 14, '&nbsp;نبوکدنضر د يروشلم خلق، ټول شهزادګان او ټول مشران سړى قېديان بوتلل چې دا ټول په شمېر کښې لس زره وُو. هغۀ سره د لوهارانو، ټول ماهِر کاريګران وويستل او په يهوداه کښې يې صِرف مسکينان خلق پرېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9651, '2 Kings 24:15', '2 Kings', 24, 15, '&nbsp;نبوکدنضر، يهوياکين د يهوياکين مور، د هغۀ ښځې، د هغۀ آفسران او د يهوداه د مشران بابل ته قېديان بوتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9652, '2 Kings 24:16', '2 Kings', 24, 16, '&nbsp;د بابل بادشاه نبوکدنضر ټول فوجيان هم وويستل چې په شمېر کښې اووۀ زره وُو، چې په جنګ کښې ښۀ تکړه وُو او ورسره يو زر ماهِر کاريګران او لوهاران هم وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9653, '2 Kings 24:17', '2 Kings', 24, 17, '&nbsp;نبوکدنضر د يهوياکين ترۀ متنياه د هغۀ په ځائ د يهوداه بادشاه جوړ کړو او د متنياه نوم يې صدقياه ته بدل کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9654, '2 Kings 24:18', '2 Kings', 24, 18, '&nbsp;صدقياه د يويشتو کالو وو چې هغه د يهوداه بادشاه جوړ شو او هغۀ په يروشلم باندې يوولس کاله بادشاهى وکړه. د هغۀ مور حموطل وه، چې د لِبناه د ښار د يرمياه لور وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9655, '2 Kings 24:19', '2 Kings', 24, 19, '&nbsp;صدقياه بادشاه د مالِک خُدائ خِلاف ګناه وکړه بلکل هم هغسې لکه چې يهويقيم بادشاه کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9656, '2 Kings 24:20', '2 Kings', 24, 20, '&nbsp;نو مالِک خُدائ د يروشلم او د يهوداه خلقو ته دومره غصه شو چې په آخر کښې يې هغوئ د خپل حضور نه لرې کړل. صدقياه د بابل بادشاه خِلاف بغاوت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9657, '2 Kings 25:1', '2 Kings', 25, 1, '&nbsp;نو د صدقياه د بادشاهۍ په نهم کال، د لسمې مياشتې په لسمه ورځ، د بابل بادشاه نبوکدنضر د خپل ټول لښکر سره د يروشلم خِلاف روان شو. هغۀ د ښار نه بهر خېمې ولګولې او د ښار نه ګېرچاپېره يې د محاصرې دېوالونه تاو کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9658, '2 Kings 25:2', '2 Kings', 25, 2, '&nbsp;او د صدقياه د بادشاهۍ تر يوولسم کال پورې يې دا محاصره کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9659, '2 Kings 25:3', '2 Kings', 25, 3, '&nbsp;هم د هغه کال د څلورمې مياشتې په نهمه ورځ، کله چې قحط دومره سخت وو چې د خلقو سره د خوراک هيڅ هم پاتې نۀ وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9660, '2 Kings 25:4', '2 Kings', 25, 4, '&nbsp;نو په يو ځائ کښې د ښار دېوال وغورزولے شو او ټول فوجيان وتښتېدل. اګر چې ښار بابليانو محاصره کړے وو خو هغوئ د شپې د دوو دېوالونو په مينځ کښې په دروازه باندې ووتل، چې دا د شاهى باغ نه شاته وه او هغوئ د اُردن وادۍ طرف ته روان شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9661, '2 Kings 25:5', '2 Kings', 25, 5, '&nbsp;خو د بابليانو لښکر په صدقياه بادشاه پسې وو، يريحو ته نزدې په مېدانونو کښې يې ونيولو او خپل ټول فوجيان ترې نه لاړل او هغه يې يواځې پرېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9662, '2 Kings 25:6', '2 Kings', 25, 6, '&nbsp;صدقياه نبوکدنضر بادشاه له بوتلے شو، چې هغه د رِبله په ښار کښې وو او هلته نبوکدنضر په هغۀ باندې سزا وخېژوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9663, '2 Kings 25:7', '2 Kings', 25, 7, '&nbsp;نو د صدقياه په مخکښې د هغۀ دوه زامن ووژلے شول، نبوکدنضر د صدقياه نه سترګې وويستلې، هغه يې د زېړو په هتکړو کښې وتړلو او بابل ته يې بوتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9664, '2 Kings 25:8', '2 Kings', 25, 8, '&nbsp;د بابل بادشاه نبوکدنضر د بادشاهۍ د نولسم کال د پينځمې مياشتې په اوومه ورځ، د بادشاه مشير او د هغۀ د لښکر مشر نبوزردان يروشلم ته وردننه شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9665, '2 Kings 25:9', '2 Kings', 25, 9, '&nbsp;هغۀ د مالِک خُدائ کور، شاهى محل او د يروشلم ټول کورونه وسوزول، هغۀ د ښار هر يو لوئ عمارت وسوزولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9666, '2 Kings 25:10', '2 Kings', 25, 10, '&nbsp;او د هغۀ فوجيانو د ښار دېوالونه راوغورزول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9667, '2 Kings 25:11', '2 Kings', 25, 11, '&nbsp;د شاهى محافظانو مشر نبوزردان، هغه خلق وويستل کوم چې په ښار کښې پاتې وُو، په دې کښې ماهِر کاريګران او هغه خلق شامل وُو چا چې د بابل بادشاه خِلاف بغاوت کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9668, '2 Kings 25:12', '2 Kings', 25, 12, '&nbsp;خو هغۀ په يهوداه کښې سخت مسکينان خلق پرېښودل، چې د انګور په باغونو او پټو کښې کَرل رېبل کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9669, '2 Kings 25:13', '2 Kings', 25, 13, '&nbsp;بابليانو د زېړو ستنې او هغه ګاډۍ ټوټې ټوټې کړې چې کومې د مالِک خُدائ په کور کښې وې، د زېړو هغه لويه ډيګۍ يې سره د ټولو زېړو بابل ته يوړله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9670, '2 Kings 25:14', '2 Kings', 25, 14, '&nbsp;هغوئ بېلچې او د قربان‌ګاه د پاکولو د ايرو لوښى هم يوړل، د ډيوو د خيال ساتلو سامان، د قربانۍ د وينې جامونه، د خوشبويۍ سوزولو لوښى او د زېړو نور ټول سامان چې د مالِک خُدائ د کور په کار کښې استعمالېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9671, '2 Kings 25:15', '2 Kings', 25, 15, '&nbsp;هغوئ هغه هر څۀ يوړل چې د سرو زرو يا سپينو زرو نه جوړ وُو، د هغه وړو جامونو او لوښو سره چې د بلو سکارو وړلو دپاره استعمالېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9672, '2 Kings 25:16', '2 Kings', 25, 16, '&nbsp;سليمان بادشاه د مالِک خُدائ د کور دپاره چې کوم سامان يې د زېړو نه جوړ کړے وو، يعنې، دوه ستنې، ګاډۍ او لويه ډيګۍ، خو د دې ټولو دومره وزن وو چې تللے نۀ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9673, '2 Kings 25:17', '2 Kings', 25, 17, '&nbsp;دواړه ستنې يو شان وې، هره يوه تقريباً نهۀ ګزه اوچته وه چې د بره د زېړو سر يې تقريباً دوه ګزه اوچت وو. د هر يو سر نه ګېرچاپېره يې د زېړو جال وو چې د زېړو نه جوړو شوو انارو باندې ښائسته کړے شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9674, '2 Kings 25:18', '2 Kings', 25, 18, '&nbsp;د دې نه علاوه، فوجى آفسر، مشر اِمام شراياه، ورپسې اِمام صفنياه او د مالِک خُدائ د کور نور درې اهم خادمان قېديان بوتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9675, '2 Kings 25:19', '2 Kings', 25, 19, '&nbsp;د ښار نه يې هغه آفسر بوتلو چې د فوجيانو مشر وو، پينځۀ د بادشاه ذاتى مشيران چې لا په ښار کښې وُو، د فوجى مشر مدد کوونکے، چې هغه د فوجى حِساب کِتاب مشر وو او شپېتۀ نور اهم سړى يې بوتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9676, '2 Kings 25:20', '2 Kings', 25, 20, '&nbsp;نبوزردان هغوئ د بابل بادشاه له بوتلل، چې هغه د رِبله په ښار کښې وو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9677, '2 Kings 25:21', '2 Kings', 25, 21, '&nbsp;چې دا د حمات په علاقه کښې دے. هلته بادشاه هغوئ ووهل او مړۀ يې کړل. نو داسې د يهوداه خلق پردى مُلک ته بوتلے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9678, '2 Kings 25:22', '2 Kings', 25, 22, '&nbsp;د بابل نبوکدنضر د سافن نمسے او د اخيقام زوئ جدلياه، د يهوداه حکمران جوړ کړو. او هغه يې په هغه ټولو باندې مشر مقرر کړو کوم چې بابل ته نۀ وُو بوتلے شوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9679, '2 Kings 25:23', '2 Kings', 25, 23, '&nbsp;کله چې د يهوداه آفسران او فوجيان د دې نه خبر شول کوم چې تسليم شوى نۀ وُو، نو هغوئ په مصفاه کښې د جدلياه سره مِلاو شول. هغه آفسران دا وُو، د نتنياه زوئ اِسمٰعيل، د قريح زوئ يوحانان، د تنحومت زوئ شراياه چې د نطوفاتى د ښار وو او د معکه يازنياه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9680, '2 Kings 25:24', '2 Kings', 25, 24, '&nbsp;جدلياه هغوئ ته ووئيل، ”زۀ تاسو ته دا خبره کوم چې د بابل د آفسرانو نه مۀ يرېږئ. په دې مُلک کښې اوسېږئ، د بابل د بادشاه خِدمت کوئ، نو ستاسو هر کار به سم وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9681, '2 Kings 25:25', '2 Kings', 25, 25, '&nbsp;خو د هغه کال په اوومه مياشت، د شاهى خاندان اليسمع نمسے او د نتنياه زوئ اِسمٰعيل د لسو کسانو سره مصفاه ته لاړو، په جدلياه يې حمله وکړه او وې وژلو. د هغۀ سره چې کوم يهوديان او بابليان وُو هغه يې هم ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9682, '2 Kings 25:26', '2 Kings', 25, 26, '&nbsp;بيا ټول اِسرائيليان، مالداره او غريبانان، سره د فوج د آفسرانو روان شول او مِصر ته لاړل، ځکه چې هغوئ د بابليانو نه يرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9683, '2 Kings 25:27', '2 Kings', 25, 27, '&nbsp;په کوم کال چې اويل‌مرودک د بابل بادشاه شو، نو هغۀ د يهوداه بادشاه په يهوياکين باندې رحم وکړو او هغه يې د قېدخانې نه آزاد کړو. دا د يهوياکين د قېدى بوتلے کېدو په اووۀ دېرشم کال د دولسمې مياشتې په اوويشتمه ورځ باندې وشول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9684, '2 Kings 25:28', '2 Kings', 25, 28, '&nbsp;اويل‌مرودک د هغۀ سره ښۀ سلوک وکړو او د هغه نورو بادشاهانو نه يې هم د لوئ عزت ځائ ورکړو کوم چې د هغۀ سره په بابل کښې جلاوطن وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9685, '2 Kings 25:29', '2 Kings', 25, 29, '&nbsp;نو يهوياکين د قېدخانې جامې بدلې کړې او باقى ټول عُمر يې د بادشاه په دسترخوان روټۍ خوړله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9686, '2 Kings 25:30', '2 Kings', 25, 30, '&nbsp;چې ترڅو هغه ژوندے وو، نو هره ورځ هغۀ ته باقاعده خرچه مِلاوېده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9687, '1 Chronicles 1:1', '1 Chronicles', 1, 1, '&nbsp;آدم د شيث پلار وو، شيث د انوش پلار وو، انوش د قېنان پلار وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9688, '1 Chronicles 1:2', '1 Chronicles', 1, 2, '&nbsp;قېنان د محلل‌اېل پلار وو، محلل‌اېل د يارد پلار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9689, '1 Chronicles 1:3', '1 Chronicles', 1, 3, '&nbsp;يارد د حنوک پلار وو او حنوک د مِتهوشله پلار وو، مِتهوشله د لمک پلار وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9690, '1 Chronicles 1:4', '1 Chronicles', 1, 4, '&nbsp;او لمک د نوح پلار وو. د نوح درې زامن وُو، شيم، حام او يافت.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9691, '1 Chronicles 1:5', '1 Chronicles', 1, 5, '&nbsp;دا د يافت اولاد دے: جُمر، ماجوج، مادى، ياوان، توبل، مسک او تيراس.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9692, '1 Chronicles 1:6', '1 Chronicles', 1, 6, '&nbsp;د جُمر اولاد: اشکناز، ريفت او تُجرمه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9693, '1 Chronicles 1:7', '1 Chronicles', 1, 7, '&nbsp;د ياوان اولاد: اِليسه، ترسيس، قبرص او رهودس.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9694, '1 Chronicles 1:8', '1 Chronicles', 1, 8, '&nbsp;دا د حام اولاد دے: کوش، مِصر، ليبيا او کنعان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9695, '1 Chronicles 1:9', '1 Chronicles', 1, 9, '&nbsp;د کوش اولاد د سِيبا، حويله، سبته، راماه او د سبتيکه خلق وُو. د راماه اولاد د شيبا او د ددان خلق وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9696, '1 Chronicles 1:10', '1 Chronicles', 1, 10, '&nbsp;کوش د نمرود پلار وو، نمرود د دُنيا وړومبے طاقتور جنګيالے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9697, '1 Chronicles 1:11', '1 Chronicles', 1, 11, '&nbsp;د مِصر اولاد د لودى، عنامى، لهابى، نفتوحى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9698, '1 Chronicles 1:12', '1 Chronicles', 1, 12, '&nbsp;فتروسى، کسلوحى او د کريت خلق وُو، چې د هغوئ اولاد فلستيان دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9699, '1 Chronicles 1:13', '1 Chronicles', 1, 13, '&nbsp;د کنعان مشرے زوئ صيدا وو. کنعان د دې قومونو هم پلار وو: حت،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
